record.field:
# ── Hermisan Health Check ──────────────────────────────────────────────
# Tests connectivity to all configured endpoints by calling BOMBEOCHECK.
# Validates Basic Auth credentials.
# ───────────────────────────────────────────────────────────────────────

Remote = self.remote_id
cfg = {}
try:
    cfg = json.loads(Remote.connection_params or '{}')
except Exception:
    cfg = {}

endpoints = cfg.get('endpoints') or {}
if not endpoints:
    raise Exception(
        "No endpoints configured. Set 'endpoints' in connection_params.")

default_tz = cfg.get('timezone', 'Europe/Madrid')
results = {}

for ep_key, ep_cfg in endpoints.items():
    ep_url = (ep_cfg.get('url') or '').rstrip('/')
    ep_user = ep_cfg.get('username', '')
    ep_pass = ep_cfg.get('password', '')

    if not ep_url:
        raise Exception(
            "Endpoint '%s': missing 'url' in connection_params." % ep_key)
    if not ep_user or not ep_pass:
        raise Exception(
            "Endpoint '%s': missing 'username' or 'password'." % ep_key)

    url = '%s/API1/BOMBEOCHECK' % ep_url
    resp = request_retry(
        'GET', url,
        auth=(ep_user, ep_pass),
        headers={'Accept': 'application/json'},
        timeout=timeout,
    )

    if resp.status_code == 401:
        raise Exception(
            "Endpoint '%s': authentication failed (HTTP 401). "
            "Check username/password. WARNING: repeated failures may "
            "trigger fail2ban." % ep_key)

    if resp.status_code >= 400:
        raise Exception(
            "Endpoint '%s': HTTP %s - %s" % (
                ep_key, resp.status_code, (resp.text or '')[:500]))

    try:
        body = resp.json() if resp.text else {}
    except Exception:
        raise Exception(
            "Endpoint '%s': invalid JSON response from BOMBEOCHECK" % ep_key)

    # BOMBEOCHECK returns false/False when the endpoint is offline
    if not body or not isinstance(body, dict):
        results[ep_key] = {
            'url': ep_url,
            'zones': 0,
            'stations': 0,
            'status': 'offline',
        }
        continue

    # Count zones and stations found
    zones = 0
    stations = 0
    for zone_name, zone_data in body.items():
        if isinstance(zone_data, dict):
            zones += 1
            for k, v in zone_data.items():
                if isinstance(v, dict):
                    stations += 1

    results[ep_key] = {
        'url': ep_url,
        'zones': zones,
        'stations': stations,
        'status': 'OK',
    }

bag['endpoints'] = endpoints
bag['health_results'] = results
bag['timezone'] = default_tz

# ── Hermisan Catalog Sync ──────────────────────────────────────────────
# GET /API1/BOMBEOCHECK on each endpoint.
# Parses the hierarchical JSON to discover:
#   - Zones (Balsas / Captaciones)
#   - Pumping Stations (Pozos) and their sensors
#   - Pumps (Bombas) and their sensors
# Produces an audit JSON attachment.
# ───────────────────────────────────────────────────────────────────────
import time as _time

Remote = self.remote_id
cfg = {}
try:
    cfg = json.loads(Remote.connection_params or '{}')
except Exception:
    cfg = {}

endpoints = bag.get('endpoints') or cfg.get('endpoints') or {}
default_tz = bag.get('timezone') or cfg.get('timezone', 'Europe/Madrid')

if not endpoints:
    raise Exception("No endpoints available. Run Health Check first.")

catalog = []
total_zones = 0
total_stations = 0
total_pumps = 0
total_variables = 0

for ep_key, ep_cfg in endpoints.items():
    ep_url = (ep_cfg.get('url') or '').rstrip('/')
    ep_user = ep_cfg.get('username', '')
    ep_pass = ep_cfg.get('password', '')

    url = '%s/API1/BOMBEOCHECK' % ep_url
    resp = request_retry(
        'GET', url,
        auth=(ep_user, ep_pass),
        headers={'Accept': 'application/json'},
        timeout=timeout,
    )

    if resp.status_code >= 400:
        raise Exception(
            "Endpoint '%s': BOMBEOCHECK failed HTTP %s - %s" % (
                ep_key, resp.status_code, (resp.text or '')[:500]))

    try:
        body = resp.json() if resp.text else {}
    except Exception:
        raise Exception(
            "Endpoint '%s': invalid JSON from BOMBEOCHECK" % ep_key)

    # BOMBEOCHECK returns false/False when the endpoint is offline
    if not body or not isinstance(body, dict):
        continue

    # Parse hierarchical structure
    for zone_name, zone_data in body.items():
        if not isinstance(zone_data, dict):
            continue

        total_zones += 1
        zone_sensors = []
        stations = []

        for key, value in zone_data.items():
            if isinstance(value, dict):
                # This is a pumping station (Pozo)
                total_stations += 1
                station_sensors = []
                pumps = []

                for var_name, var_value in value.items():
                    if isinstance(var_value, dict):
                        # This is a pump (Bomba)
                        total_pumps += 1
                        pump_sensors = []
                        for pvar_name, pvar_value in var_value.items():
                            if not isinstance(pvar_value, dict):
                                pump_sensors.append({
                                    'variable': pvar_name,
                                    'current_value': pvar_value,
                                })
                                total_variables += 1
                        pumps.append({
                            'name': var_name,
                            'sensors': pump_sensors,
                        })
                    else:
                        # Station-level sensor
                        station_sensors.append({
                            'variable': var_name,
                            'current_value': var_value,
                        })
                        total_variables += 1

                stations.append({
                    'name': key,
                    'sensors': station_sensors,
                    'pumps': pumps,
                })
            else:
                # Zone-level sensor (e.g. Altura embalses)
                zone_sensors.append({
                    'variable': key,
                    'current_value': value,
                })
                total_variables += 1

        catalog.append({
            'endpoint_key': ep_key,
            'zone_name': zone_name,
            'zone_sensors': zone_sensors,
            'stations': stations,
        })

    _time.sleep(60)

# ── Create audit attachment ────────────────────────────────────────────
audit = {
    'executed_at': fields.Datetime.now(),
    'total_zones': total_zones,
    'total_stations': total_stations,
    'total_pumps': total_pumps,
    'total_variables': total_variables,
    'catalog': catalog,
}

json_str = json.dumps(audit, ensure_ascii=False, indent=2)
encoded = base64.b64encode(json_str.encode('utf-8'))
fname = 'hermisan_catalog_%s.json' % (
    fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_'))

att = env['ir.attachment'].create({
    'name': fname,
    'datas_fname': fname,
    'datas': encoded,
    'mimetype': 'application/json',
    'res_model': 'remotecontrol',
    'res_id': Remote.id,
})

Remote.message_post(
    body=u'[Hermisan] Catalog sync: zones=%s stations=%s pumps=%s '
         u'variables=%s' % (
             total_zones, total_stations, total_pumps, total_variables),
    attachment_ids=[att.id],
)

bag['catalog'] = catalog
bag['catalog_attachment_id'] = att.id

# ── Hermisan: Provision Devices ────────────────────────────────────────
# Auto-creates mdm.measurement.device and mdm.measurement.device.sensor
# records from the catalog discovered via BOMBEOCHECK + BOMBEOSTATS.
#
# Strategy:
#   1. BOMBEOCHECK (from catalog) → structure (zones, stations, pumps)
#   2. BOMBEOSTATS (last 7 days) → real variable names per station/pump
#   3. Create sensors using BOMBEOSTATS names (exact match for readings)
#
# Mapping:
#   Hermisan Pumping Station (Pozo)  → one mdm.measurement.device
#   Hermisan variable (per station)  → one mdm.measurement.device.sensor
#   Hermisan variable (per pump)     → one mdm.measurement.device.sensor
#
# Idempotent: matches by (endpoint_key, pozo_key) for devices and
# (device_id, variable, bomba) for sensors.
# ───────────────────────────────────────────────────────────────────────
import time as _time
from datetime import datetime, timedelta

Remote = self.remote_id
catalog = bag.get('catalog') or []

if not catalog:
    raise Exception(
        "No catalog in bag. Run Sync Catalog action first.")

cfg = {}
try:
    cfg = json.loads(Remote.connection_params or '{}')
except Exception:
    cfg = {}

endpoints = bag.get('endpoints') or cfg.get('endpoints') or {}

Device = env['mdm.measurement.device']
Sensor = env['mdm.measurement.device.sensor']
SensorType = env['mdm.measurement.device.sensor.type']
SensorUom = env['mdm.measurement.device.sensor.uom']

remotecontrol_ref = env.ref(
    'remotecontrol_hermisan.remotecontrol_hermisan')

# ── Call BOMBEOSTATS on each endpoint to discover variable names ───────
# This gives us the REAL names that will appear in readings import.
today = datetime.strptime(fields.Date.today(), '%Y-%m-%d')
from_dt = today - timedelta(days=7)
from_str = from_dt.strftime('%Y.%m.%d-00:00:00')
to_str = today.strftime('%Y.%m.%d-23:59:59')

# Structure: {endpoint_key: {pozo_name: {station_vars: set, pumps: {bomba: set}}}}
stats_vars = {}

for ep_key, ep_cfg in endpoints.items():
    ep_url = (ep_cfg.get('url') or '').rstrip('/')
    ep_user = ep_cfg.get('username', '')
    ep_pass = ep_cfg.get('password', '')
    if not ep_url or not ep_user:
        continue

    url = '%s/API1/BOMBEOSTATS?from=%s&to=%s' % (
        ep_url, from_str, to_str)

    try:
        resp = request_retry(
            'GET', url,
            auth=(ep_user, ep_pass),
            headers={'Accept': 'application/json'},
            timeout=timeout,
        )
    except Exception:
        continue

    if resp.status_code != 200:
        continue

    try:
        body = resp.json() if resp.text else {}
    except Exception:
        continue

    if body is False or body is None or not isinstance(body, dict):
        continue

    rows = body.get('rows', [])
    ep_vars = {}

    # Known non-variable fields to skip
    SKIP_FIELDS = {
        '_balsa', 'Balsa', 'Fecha', '_pozo', 'Pozo', 'Marcha',
        '_timeStart', '_timeEnd', '_bombas', 'Bombas', 'ID',
    }

    for row in rows:
        if not isinstance(row, dict):
            continue
        pozo_name = row.get('Pozo', '')
        if not pozo_name:
            continue

        if pozo_name not in ep_vars:
            ep_vars[pozo_name] = {'station_vars': set(), 'pumps': {}}

        # Station-level: any numeric field not in SKIP_FIELDS
        for key, val in row.items():
            if key in SKIP_FIELDS:
                continue
            if val is not None:
                try:
                    float(val)
                    ep_vars[pozo_name]['station_vars'].add(key)
                except (ValueError, TypeError):
                    pass

        # Pump-level
        bombas = row.get('_bombas') or {}
        if isinstance(bombas, dict):
            for bomba_name, bomba_data in bombas.items():
                if not isinstance(bomba_data, dict):
                    continue
                if bomba_name not in ep_vars[pozo_name]['pumps']:
                    ep_vars[pozo_name]['pumps'][bomba_name] = set()
                for bvar, bval in bomba_data.items():
                    if bval is not None:
                        try:
                            float(bval)
                            ep_vars[pozo_name]['pumps'][
                                bomba_name].add(bvar)
                        except (ValueError, TypeError):
                            pass

    stats_vars[ep_key] = ep_vars
    _time.sleep(60)

# ── UOM cache ──────────────────────────────────────────────────────────
uom_cache = {}

VARIABLE_UOMS = {
    u'Caudal impulsión': u'm\u00b3/h',
    u'Presión impulsión': u'bar',
    u'Potencia Consumida': u'kW\u00b7h',
    u'Altura embalses': u'mca',
    u'Agua': u'm\u00b3',
}

def _get_uom(unit_name):
    if not unit_name:
        unit_name = u'-'
    if unit_name in uom_cache:
        return uom_cache[unit_name]
    uom = SensorUom.search([('name', '=', unit_name)], limit=1)
    if not uom:
        uom = SensorUom.create({
            'name': unit_name,
            'abbreviation': unit_name,
            'description': u'Auto-created from Hermisan',
        })
    uom_cache[unit_name] = uom
    return uom

# ── Sensor Type cache ──────────────────────────────────────────────────
type_cache = {}

def _get_sensor_type(var_name, uom):
    full_name = u'%s (%s)' % (var_name, uom.name)
    if full_name in type_cache:
        return type_cache[full_name]
    stype = SensorType.search([('name', '=', full_name)], limit=1)
    if not stype:
        stype = SensorType.create({
            'name': full_name,
            'description': u'Auto-created from Hermisan (%s)' % var_name,
            'uom_id': uom.id,
        })
    type_cache[full_name] = stype
    return stype

# ── Existing devices map: (endpoint_key, pozo_key) → device ───────────
existing_devices = {}
all_devices = Device.search([
    ('remotecontrol_id', '=', remotecontrol_ref.id),
])
for dev in all_devices:
    try:
        dev_cfg = json.loads(dev.remotecontrol_params or '{}')
    except Exception:
        dev_cfg = {}
    dk = (dev_cfg.get('endpoint_key', ''), dev_cfg.get('pozo_key', ''))
    if dk[0] and dk[1]:
        existing_devices[dk] = dev

# ── Existing sensors map: (device_id, variable, bomba) → sensor ───────
existing_sensors = {}
all_sensors = Sensor.search([
    ('device_id.remotecontrol_id', '=', remotecontrol_ref.id),
])
for sen in all_sensors:
    try:
        sen_cfg = json.loads(sen.remotecontrol_params or '{}')
    except Exception:
        sen_cfg = {}
    variable = sen_cfg.get('variable', '')
    bomba = sen_cfg.get('bomba', '')
    if variable:
        existing_sensors[(sen.device_id.id, variable, bomba)] = sen

total_devices_created = 0
total_devices_existing = 0
total_sensors_created = 0
total_sensors_existing = 0
device_details = []

def _create_sensor_if_needed(device, var_name, bomba_name=''):
    """Create a sensor for a device if it doesn't exist."""
    global total_sensors_created, total_sensors_existing
    sensor_key = (device.id, var_name, bomba_name)
    if sensor_key in existing_sensors:
        total_sensors_existing += 1
        return

    unit_name = VARIABLE_UOMS.get(var_name, u'-')
    uom = _get_uom(unit_name)
    stype = _get_sensor_type(var_name, uom)

    sensor_name = var_name
    if bomba_name:
        sensor_name = u'%s - %s' % (var_name, bomba_name)

    sensor_params = {'variable': var_name}
    if bomba_name:
        sensor_params['bomba'] = bomba_name

    sensor = Sensor.create({
        'name': sensor_name,
        'device_id': device.id,
        'type_id': stype.id,
        'remotecontrol_params': json.dumps(
            sensor_params, ensure_ascii=False),
    })
    existing_sensors[sensor_key] = sensor
    total_sensors_created += 1

for zone_data in catalog:
    ep_key = zone_data.get('endpoint_key', '')
    zone_name = zone_data.get('zone_name', '')
    stations = zone_data.get('stations', [])

    ep_stats = stats_vars.get(ep_key, {})

    for station in stations:
        pozo_key = station.get('name', '')
        if not pozo_key:
            continue

        dev_lookup = (ep_key, pozo_key)
        device = existing_devices.get(dev_lookup)

        if device:
            total_devices_existing += 1
        else:
            dev_name = u'%s - %s' % (zone_name, pozo_key)
            dev_params = {
                'endpoint_key': ep_key,
                'pozo_key': pozo_key,
                'zone_key': zone_name,
            }
            device = Device.create({
                'name': dev_name,
                'description': u'Hermisan station: %s (zone: %s, '
                               u'endpoint: %s)' % (
                                   pozo_key, zone_name, ep_key),
                'remotecontrol_id': remotecontrol_ref.id,
                'remotecontrol_params': json.dumps(
                    dev_params, ensure_ascii=False),
            })
            existing_devices[dev_lookup] = device
            total_devices_created += 1

        sensors_before = total_sensors_created

        # Use BOMBEOSTATS variable names (real names for readings)
        pozo_stats = ep_stats.get(pozo_key, {})
        station_vars = pozo_stats.get('station_vars', set())
        pump_vars = pozo_stats.get('pumps', {})

        # Station-level sensors from BOMBEOSTATS
        for var_name in sorted(station_vars):
            _create_sensor_if_needed(device, var_name)

        # Pump-level sensors from BOMBEOSTATS
        for bomba_name in sorted(pump_vars.keys()):
            for var_name in sorted(pump_vars[bomba_name]):
                _create_sensor_if_needed(device, var_name, bomba_name)

        # Fallback: if BOMBEOSTATS had no data for this station,
        # use BOMBEOCHECK structure (from catalog)
        if not station_vars and not pump_vars:
            for ss in station.get('sensors', []):
                _create_sensor_if_needed(
                    device, ss.get('variable', ''))
            for pump in station.get('pumps', []):
                pump_name = pump.get('name', '')
                for ps in pump.get('sensors', []):
                    _create_sensor_if_needed(
                        device, ps.get('variable', ''), pump_name)

        device_details.append({
            'endpoint_key': ep_key,
            'zone_name': zone_name,
            'pozo_key': pozo_key,
            'device_id': device.id,
            'sensors_created': total_sensors_created - sensors_before,
            'source': 'BOMBEOSTATS' if (station_vars or pump_vars)
                      else 'BOMBEOCHECK',
        })

# ── Create audit attachment ────────────────────────────────────────────
audit = {
    'executed_at': fields.Datetime.now(),
    'total_devices_created': total_devices_created,
    'total_devices_existing': total_devices_existing,
    'total_sensors_created': total_sensors_created,
    'total_sensors_existing': total_sensors_existing,
    'devices': device_details,
}

b64 = base64.b64encode(
    json.dumps(audit, ensure_ascii=False, indent=2).encode('utf-8'))
fname = 'hermisan_provision_%s.json' % (
    fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_'))

att = env['ir.attachment'].create({
    'name': fname,
    'datas_fname': fname,
    'datas': b64,
    'mimetype': 'application/json',
    'res_model': 'remotecontrol',
    'res_id': Remote.id,
})

Remote.message_post(
    body=u'[Hermisan] Provision: devices_created=%s devices_existing=%s '
         u'sensors_created=%s sensors_existing=%s' % (
             total_devices_created, total_devices_existing,
             total_sensors_created, total_sensors_existing),
    attachment_ids=[att.id],
)

bag['provision_audit'] = audit
bag['provision_attachment_id'] = att.id

# ── Hermisan: Build Sensor Plan ────────────────────────────────────────
# Reads mdm.measurement.device.sensor records linked to this
# remotecontrol and builds the plan for BOMBEOSTATS calls.
#
# Groups sensors by endpoint for efficient API calls (one BOMBEOSTATS
# call per endpoint returns all stations).
# ───────────────────────────────────────────────────────────────────────

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
today_str = fields.Date.today()

cfg = {}
try:
    cfg = json.loads(Remote.connection_params or '{}')
except Exception:
    cfg = {}

endpoints = bag.get('endpoints') or cfg.get('endpoints') or {}
default_tz = cfg.get('timezone', 'Europe/Madrid')
bag['endpoints'] = endpoints

condition = [
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id),
]

if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))

sensors = Sensor.search(condition)

# Build map of sensor_id -> most recent reading (single query)
last_readings_map = {}
if sensors:
    sensor_ids = [s.id for s in sensors]
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for row in cr.fetchall():
        last_readings_map[row[0]] = row[1]

# Group sensors by endpoint
# Structure: { endpoint_key: { sensors: [...], earliest_date: ... } }
endpoints_plan = {}
sensors_plan = []

for sensor in sensors:
    device = sensor.device_id

    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}

    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}

    ep_key = device_cfg.get('endpoint_key', '')
    pozo_key = device_cfg.get('pozo_key', '')
    variable = sensor_cfg.get('variable', '')
    bomba = sensor_cfg.get('bomba', '')

    if not ep_key or not pozo_key or not variable:
        continue

    # Determine start date
    start_cfg = (sensor_cfg.get('start_date') or
                 device_cfg.get('start_date'))
    last_reading_time = last_readings_map.get(sensor.id)

    if last_reading_time:
        try:
            initial_date = fields.Date.to_string(
                fields.Datetime.from_string(last_reading_time))
        except Exception:
            initial_date = str(last_reading_time)[:10]
    elif start_cfg:
        initial_date = start_cfg[:10]
    else:
        year_str = today_str[:4]
        initial_date = '%s-01-01' % year_str

    if isinstance(initial_date, unicode):
        initial_date = initial_date.encode('utf-8')

    sensor_entry = {
        'sensor_id': sensor.id,
        'device_id': device.id,
        'endpoint_key': ep_key,
        'pozo_key': pozo_key,
        'variable': variable,
        'bomba': bomba,
        'initial_date': initial_date,
    }
    sensors_plan.append(sensor_entry)

    if ep_key not in endpoints_plan:
        endpoints_plan[ep_key] = {
            'sensors': [],
            'earliest_date': initial_date,
        }
    endpoints_plan[ep_key]['sensors'].append(sensor_entry)
    if initial_date < endpoints_plan[ep_key]['earliest_date']:
        endpoints_plan[ep_key]['earliest_date'] = initial_date

bag['sensors_plan'] = sensors_plan
bag['endpoints_plan'] = endpoints_plan
